$data = json_decode($json_data, true);

foreach ($data as $test) {
    echo "\n--- Processing Assessment: '{$test['title']}' ---\n";
    
    // Check if assessment already exists
    $chk_a = $db->query("SELECT id FROM assessments WHERE title = '" . $db->real_escape_string($test['title']) . "' OR slug = '" . $db->real_escape_string($test['slug']) . "' LIMIT 1");
    if ($chk_a && $chk_a->num_rows > 0) {
        $a_row = $chk_a->fetch_assoc();
        $assessment_id = $a_row['id'];
        $db->query("UPDATE assessments SET title = '" . $db->real_escape_string($test['title']) . "', slug = '" . $db->real_escape_string($test['slug']) . "', description = '" . $db->real_escape_string($test['description']) . "', time_limit = {$test['time_limit']}, status = 'active' WHERE id = {$assessment_id}");
        echo "Updated existing assessment ID: {$assessment_id}\n";
    } else {
        $stmt = $db->prepare("INSERT INTO assessments (title, slug, description, time_limit, status, created_at) VALUES (?, ?, ?, ?, 'active', NOW())");
        $stmt->bind_param("sssi", $test['title'], $test['slug'], $test['description'], $test['time_limit']);
        $stmt->execute();
        $assessment_id = $db->insert_id;
        echo "Created new assessment ID: {$assessment_id}\n";
    }
    
    // Delete existing parts & questions for this assessment to cleanly re-seed
    $db->query("DELETE FROM questions WHERE assessment_id = {$assessment_id}");
    $db->query("DELETE FROM assessment_parts WHERE assessment_id = {$assessment_id}");
    
    $total_q_inserted = 0;
    
    foreach ($test['parts'] as $part) {
        $stmt_p = $db->prepare("INSERT INTO assessment_parts (assessment_id, part_name, description, created_at) VALUES (?, ?, ?, NOW())");
        $stmt_p->bind_param("iss", $assessment_id, $part['part_name'], $part['description']);
        $stmt_p->execute();
        $part_id = $db->insert_id;
        
        foreach ($part['questions'] as $q) {
            $stmt_q = $db->prepare("INSERT INTO questions (assessment_id, part_id, subject, question_number, question_text, option_a, option_b, option_c, option_d, correct_option) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
            $stmt_q->bind_param("iisissssss", $assessment_id, $part_id, $part['part_name'], $q['question_number'], $q['question_text'], $q['option_a'], $q['option_b'], $q['option_c'], $q['option_d'], $q['correct_option']);
            $stmt_q->execute();
            $total_q_inserted++;
        }
    }
    
    echo "Successfully inserted " . count($test['parts']) . " parts and {$total_q_inserted} questions into Assessment ID {$assessment_id}.\n";
}

echo "\n=== SEEDING COMPLETED SUCCESSFULLY ===\n";
$db->close();
